  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Observe o triângulo amarelo. Sua área é (2×8)/2 = 8 cm². Logo, a área do triângulo azul é 4 cm². Como o quadrado tem área 64 cm², o quadrilátero rosa tem área 64 − 8 − 4 = 52 cm²."}]$j$::jsonb where id = '035d2537-bb8b-4c01-a1e9-8e9a9cc04a7a'::uuid and blocos is null;
