  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2023_N2_Q06_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '05f6e5fc-46fc-4c4a-baef-23f585981ade'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A figura representa um quadrante (um quarto) da circunferência na qual estão localizadas as cabines igualmente espaçadas. No interior do quadrante contamos 5 cabines e nos dois limites do quadrante vemos que também há cabines, vistas parcialmente. Portanto, o número total de cabines da roda gigante é igual a 4 x 5 = 20 no interior dos quadrantes e mais 4 cabines que ficam sobre os lados dos quadrantes, totalizando 20 + 4 = 24 cabines."}]$j$::jsonb where id = '062de499-aa9e-47e7-ba80-c84a5a82fddc'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2018_N1_2F_Q06_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '06d62647-9715-47c6-a950-0f2bb24702b0'::uuid and blocos is null;
