  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N1_Q08_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '06ff00bd-45ed-4f3f-9b54-b71f7a66e6b3'::uuid and blocos is null;
