  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2016_N2_1F_Q06_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '079796ac-63f0-4adf-822a-010a483d9edf'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2017_N1_2F_Q05_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0830cfa0-1ecd-4903-985b-f2023ae301bb'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como indicado na figura ao lado, vamos chamar de A o cano que se ramifica em três saídas, sendo uma delas a saída X, e de B o cano que se ramifica em duas saídas, sendo uma delas a saída Y. Como a água que passa pelos canos distribui-se igualmente em cada ramificação, pelo cano A passa, por hora, 3 vezes a quantidade de água que passa pela saída X, enquanto pelo cano B passa, por hora, 2 vezes a quantidade de água que passa pela saída Y. Como os canos A e B são as únicas saídas de uma mesma ramificação, a quantidade de água que passa por eles em uma hora é a mesma. Assim, 3 vezes a quantidade de água que passa por hora pela saída X é igual a 2 vezes a quantidade de água por hora que passa pela saída Y. Mas, a quantidade de água que passa por X é 200 mil litros; logo, a quantidade de água que passa pela saída Y por hora é a metade de 600 mil litros, ou seja, 300 mil litros."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780786246707-tugy2j8itzp.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '08fce70e-be06-4d03-b405-700eb79f4026'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2016_N2_1F_Q01_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '096a8578-720b-41cd-b66d-cabb09443cde'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781100443212-5712fb0iy8k.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0980b738-0c77-4018-be1c-034e735cfd07'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2018_N2_1F_Q06_sol.png","tipo":"imagem"}]$j$::jsonb where id = '09b74ee9-81fa-4c5d-96ea-1f7386ef3505'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como mostra a figura, os nomes das notas se repetem de 12 em 12. Portanto, a nota que está 17 semitons acima da nota Lá tem o mesmo nome da nota que está 17 − 12 = 5 semitons acima da nota Lá, que é a nota Ré (Lá# – Si – Dó – Dó# – Ré)."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780925229876-3amul167pzv.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '09cffe0d-efd7-4d36-a5c5-05e62738dc8e'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N1_Q05_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '09e3cd84-97bf-44be-87e9-ffee8dd9e838'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2015_N3_1F_Q15_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0a1394c0-30b9-4d83-a6ea-ba2eed957f61'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2022_N3_1F_Q19_sol.png","tipo":"imagem"}]$j$::jsonb where id = '0a2b0c33-44e4-4f07-a7df-27bd9713357f'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OMERJ2025_N3_Q03_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0a3aedac-68b6-412f-8fe5-9245f05229fc'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2017_N2_1F_Q20_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0ab772d5-94d5-4a1b-a5df-36c398f27a7d'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Para obter 30 litros de tinta marrom, precisaremos de 15 litros de cada uma das cores laranja e verde. A primeira condição nos diz que, para obter essa quantidade de tinta laranja, precisaremos da fração 2/3+2 = 2/5 da quantidade total exclusivamente de tinta amarela, ou seja, 2/5 x 15 = 6 litros de tinta amarela. Da mesma forma, a segunda condição nos diz que, para obter 15 litros de tinta verde, precisaremos da fração 1/2+1 = 1/3 da quantidade total\nexclusivamente de tinta amarela, ou seja, 1/3 x 15 = 5 litros de tinta amarela. Portanto, a quantidade total de tinta amarela necessária é 5 + 6 = 11 litros."}]$j$::jsonb where id = '0b9ab4a4-e9bc-4cb2-996f-b452e10f01e9'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781461410570-czcykgxts9j.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781461429279-b7p7re2d1de.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0bc4ccc2-dbe9-4eef-843f-37dd222942c7'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2023_N2_Q20_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0c3c1bed-5f98-4384-82f4-93227d6974e0'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Cada menina tem um menino ou uma menina à sua direita. Portanto, das duas primeiras informações dadas podemos concluir que há um total de 7 + 9 = 16 meninas. Da terceira informação podemos concluir que 1 − (2/5) = 3/5 dos meninos têm uma menina à sua esquerda, ou seja, 3/5 dos meninos representa o total de meninos com um menino à sua direita (9). Portanto, há um total de (5/3) × 9 = 15 meninos. Finalmente, podemos concluir que o grupo inteiro tem 16 + 15 = 31 integrantes. Um esboço de como a roda pode ter sido formada é o seguinte:"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780932179658-3wk83rx4knd.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '0c69a0bd-c934-4dd1-ba52-df662fc6bb7c'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N2_Q15_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0c83f03b-181a-424c-b97d-0feebb3f60b2'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781466877140-oy5litmo4yp.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781466890352-v7riqja0lw.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0cf0bf4f-ef2d-4860-a92d-5daee635e364'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A nota média dos quatro alunos é dada pela soma das quatro notas dividida por 4. Logo, como a média é 7,0, a soma das quatro notas é 4 x 7 = 28.\nAssim, a soma das cinco notas é 28 + 8 = 36, o que nos fornece média 36 ÷ 5 = 7,2. "}]$j$::jsonb where id = '0d10a17d-b6c1-422c-aa92-ae439f71d987'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2022_N2_Q10_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0dbeea6a-9a6e-45df-96b2-4c05cb15bafd'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Usando a figura e lembrando que o sentido da contagem muda aos serem falados os números 7, 14, 21, 28, podemos verificar que os números a serem falados por Ana e Beatriz serão:\n\nAna: 1, 6, 8, 13, 15, 20, 22, 27, 29, ...\nBeatriz: 2, 7, 12, 16, 21, 26, 30, ...\n\nComo a contagem 29, 30, 31, 32 será feita no sentido horário, concluímos que Carolina dirá o número 31 e Diana falará o número 32.\n\nOutra solução: Como o sentido muda em Beatriz ao dizer 7, muda em Elaine ao dizer 14, muda em Beatriz ao dizer 21, muda em Elaine ao dizer 28, voltando ao sentido horário, Ana dirá 29, Beatriz 30, Carolina 31 e Diana 32."}]$j$::jsonb where id = '0dfb9bdd-0e73-4e4f-917e-9ec991f35820'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2015_N3_1F_Q02_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0e38b9d5-e0ac-4e64-85b4-63cdacaf2c69'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780944753212-hwj50fzw2w.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0ea20e51-a04d-426f-88f3-0df2bdfd0756'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OMERJ2024_N4_Q02_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0ecf3492-51c9-4270-962c-be7b4ff8f26f'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780952703369-las2u8ceplk.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '0ecf7392-9b0e-4af2-995b-290819f480e2'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Consideramos dois casos:\na) O motorista do primeiro carro decide estacionar em uma das vagas marcadas com os números 1 ou 10. Para cada uma dessas escolhas, o segundo motorista terá 8 opções disponíveis de estacionamento; logo, nesse caso, há um total de 2 × 8 = 16 maneiras diferentes para o estacionamento dos carros (utilizamos aqui o Princípio Multiplicativo da Contagem).\nb) O motorista do primeiro carro decide estacionar em uma das vagas marcada com os números 2, 3, 4, 5, 6, 7, 8 ou 9. Para cada uma dessas escolhas, o segundo motorista terá 7 opções disponíveis de estacionamento; logo, nesse caso, há um total de 8 × 7 = 56 maneiras diferentes para o estacionamento dos carros.\n\nDe acordo com as situações anteriores, há um total de 16 + 56 = 72 maneiras diferentes para o estacionamento dos carros (utilizamos aqui o Princípio Aditivo da Contagem)."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780844372759-86t4ipy83mf.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '0eed27c4-da65-4387-a6ff-e325c2da0764'::uuid and blocos is null;
