  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Desfazendo a segunda dobra, abrimos verticalmente a folha, obtendo:"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780856374575-bhmjnzn5jkv.png","tipo":"imagem","largura":"media"},{"tipo":"texto","conteudo":"Em seguida, ao desfazer a primeira dobra, abrimos horizontalmente a folha, obtendo:"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780856450883-k2cwv08nwk.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '13257f5f-7bc1-457c-b2f3-819a2b122e00'::uuid and blocos is null;
