  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Observemos que os três triângulos da Figura 2 são congruentes (portanto, têm mesma área). De fato, são três triângulos retângulos isósceles com os correspondentes lados de mesma medida (pode ser verificado facilmente no quadriculado). Consequentemente, a área pintada, que é exatamente a de um triângulo, corresponde à fração 1/3.\n\nOs seis retângulos que constituem a Figura 3 são congruentes. Como a área pintada é formada por dois desses retângulos, segue que a área pintada na Figura 3 corresponde a 2/6 = 1/3 da área total da Figura 3.\n\nPor outro lado, na Figura 4, observamos cinco triângulos congruentes, sendo que apenas dois estão pintados, os quais correspondem à fração 2/5.\n\nFinalmente, na Figura 5, temos um triângulo isósceles formado por dois triângulos retângulos congruentes, sendo que apenas um deles está pintado. Logo, a área pintada corresponde à fração 1/2.\n\nComo 1/4 < 1/3 = 2/6 < 2/5 < 1/2, a maior fração corresponde à área pintada na Figura 5, a saber, 1/2.\n\nEsta questão serve para exemplificar que devemos ter muito cuidado ao comparar frações, pois, entre diferentes figuras, a fração numericamente maior pode não corresponder visualmente à maior área pintada."}]$j$::jsonb where id = '289df4a5-ea2e-4f29-9f6a-cce4d105d073'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2024_N2_1F_Q18_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '28c7eb21-ce05-4535-803c-fac2b8e7dd06'::uuid and blocos is null;
