  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"O caminho percorrido por Miguel é AD + DC + CF + FA. Como AB = BC, pois B é ponto médio de AC, e DE = EF, pois E é ponto médio de DF, então o caminho percorrido por Miguel mede\n\nAD + DC + CF + FA = (AB + BC + CD) + DC + (CD + DE + EF) + (FE + ED + DC + CB + BA) =\n= (BC + BC + CD) + DC + (CD + DE + ED) + (DE + ED + DC + CB + BC) =\n= 4 × BC + 4 × CD + 4 × DE = 4 × (BC + CD + DE) = 4 × BE = 4 × 900 = 3600 m."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780930691430-eoe7v0w0w6p.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '2a3b296c-11c8-45c4-9926-972a10ad95ae'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2015_N3_1F_Q01_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '2aec91c3-8ddd-45ee-a115-ecac206e1b82'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2017_N2_1F_Q05_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '2b3104fe-68db-4e0b-ad5e-829604c65c8b'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Vamos simular a montagem da Figura 1, colocando a peça da Figura 2 sobre ela. Observe que, dentre as quatro posições possíveis para colocar a peça da Figura 2 sobre a Figura 1, mostradas na figura ao lado, apenas a última está de acordo com o enunciado. De fato, usando qualquer uma das outras três posições, a parte descoberta da Figura 1 ficará separada em duas ou mais regiões, sendo necessário, pelo menos, mais duas peças para cobri-la. Nesse caso, vemos que a peça complementar utilizada para formar a Figura 1 é a peça da alternativa A."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780678581360-wbvlg3jpc39.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '2b3246d6-591a-45ee-b1d1-3241c63b5d2d'::uuid and blocos is null;
