  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N3_Q12_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '2dd7029c-030b-41f5-a001-aae324b152fa'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OMERJ2025_N4_Q05_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '2dfca3a1-882e-43bf-8bb1-8a8646f7ba5d'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Vamos pensar nas netas como as letras A, B, C, D e E e descrever a ordem em que elas chegaram como uma sequência dessas letras, lida da esquerda para a direita. O enunciado nos diz que nessa sequência\n\n1. o B está à esquerda do A (Beatriz chegou antes de Ana);\n2. o B está à direita do D (Beatriz chegou depois de Daniela);\n3. o bloco CDE aparece sem letras intermediárias e com as letras nessa ordem (Cláudia, Daniela e Érica chegaram uma em seguida da outra, nessa ordem).\n\nAs informações 2 e 3 mostram que o B aparece à direita do bloco CDE, e a informação 1 diz que o A está à direita do B. A nossa sequência é, então, CDEBA, e concluímos que a primeira a chegar foi Cláudia."}]$j$::jsonb where id = '2e2e5db9-9b23-4d08-bfc8-5b875900eb20'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A figura apresentada tem um total de 24 quadradinhos. Para que o número de quadradinhos pretos seja o dobro do número de quadradinhos brancos, os quadradinhos pretos devem representar 2/3 do total, que correspondem a 16 quadradinhos, e os brancos 1/3 do total, que correspondem a 8 quadradinhos. Como na figura original há 5 quadradinhos pretos, é preciso pintar de preto 16 - 5 = 11 quadradinhos.\n\nOutra solução: Uma forma de pintar os quadradinhos de modo que o número de pretos seja o dobro do de brancos é fazer com que isto ocorra em cada linha, ou seja, de modo que cada linha tenha 4 quadradinhos pretos e 2 brancos. Para tal, é preciso pintar nas sucessivas linhas 3, 2, 3 e 3 quadradinhos (um total de 11 quadradinhos) para que o número de quadradinhos pretos passe a ser o dobro do número de quadradinhos brancos.\n"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780784552556-2gzovsv4oyo.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '2e54fea9-0294-4453-9146-c70a56e608b1'::uuid and blocos is null;
