  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Consideramos dois casos:\na) O motorista do primeiro carro decide estacionar em uma das vagas marcadas com os números 1 ou 10. Para cada uma dessas escolhas, o segundo motorista terá 8 opções disponíveis de estacionamento; logo, nesse caso, há um total de 2 × 8 = 16 maneiras diferentes para o estacionamento dos carros (utilizamos aqui o Princípio Multiplicativo da Contagem).\nb) O motorista do primeiro carro decide estacionar em uma das vagas marcada com os números 2, 3, 4, 5, 6, 7, 8 ou 9. Para cada uma dessas escolhas, o segundo motorista terá 7 opções disponíveis de estacionamento; logo, nesse caso, há um total de 8 × 7 = 56 maneiras diferentes para o estacionamento dos carros.\n\nDe acordo com as situações anteriores, há um total de 16 + 56 = 72 maneiras diferentes para o estacionamento dos carros (utilizamos aqui o Princípio Aditivo da Contagem)."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780844372759-86t4ipy83mf.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '37e38396-ee87-43a5-8f2d-8d8696222080'::uuid and blocos is null;
