  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780843011270-o8clx0ab0g.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '39d130cf-6ae6-42c0-97e3-b6c11a51282e'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como as letras P, Q, S e T estão visíveis na ilustração, essas são as faces adjacentes à face com a letra O, e a face oposta à letra O é a face com a letra R. As faces em contato entre os dados 1 e 2 não podem ser P (visível na ilustração do dado 1), nem Q ou S (visíveis na ilustração do dado 2). Portanto, tem que ser T. Olhando para o dado 2, concluímos que a face com S é oposta à face com T.\n\nOutra solução: A letra O possui quatro faces vizinhas com as letras P, Q, S e T. Primeiramente observe que Zequinha juntou o dado 2 com o dado 3 pela face P, pois esta mesma face não pode estar na junção do dado 2 com o dado 1, que possui a face P visível. Logo, os dados 1 e 2 foram juntados pela face T. Assim, S e T são faces opostas, o que responde à questão. É claro também que P é oposta a Q, bem como R, que não aparece na ilustração, é oposta a O."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780792413432-0d6yod7qmhru.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '39f7cfcd-37d0-4019-82b2-e9401387fb86'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2023_N2_Q02_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '3a02d7a9-05aa-4eb2-820a-b8c3b1511973'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2025_N2_1F_Q11_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '3a264414-4d59-4f6b-8483-ff70cb09b6f4'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780709280293-2ultt9apttl.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '3a31fc8a-9411-4473-927b-1668e6e5cf4c'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781105548435-8x8nb40jn2f.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '3af5d43f-ea2b-4367-b1cc-99a71bf2e7ff'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Por observação direta da ilustração, vemos que o edifício A tem 12 janelas na frente. Logo, tem 11 ou menos janelas atrás. O edifício B tem 10 janelas na frente. Logo, tem 11 ou mais janelas atrás. Como os dois prédios têm o mesmo número de janelas na parte de trás, concluímos que esse número só pode ser 11. Como nas laterais não há janelas, os dois edifícios juntos têm 12 + 11 + 10 + 11 = 44 janelas."}]$j$::jsonb where id = '3b1fda26-3e59-43db-b379-b3ef5cd37a90'::uuid and blocos is null;
