  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Para facilitar, vamos rotular cada hexágono com uma letra, de A a F.\n\nComo no hexágono F está marcado 2, os hexágonos D e E têm versos azuis, pois são os únicos vizinhos de F. Como no hexágono B está marcado 3, seus vizinhos, os hexágonos A, C e D, têm versos azuis. Como no hexágono E está marcado 2 e ele é vizinho de C e D, que têm versos azuis, o hexágono F **não** tem verso azul. Finalmente, como no hexágono A está marcado 1 e ele é vizinho de D, que tem verso azul, o hexágono B **não** tem verso azul. Portanto, os hexágonos que têm verso azul são: A, C, D e E, um total de 4."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780923479500-0gsdeuq6knh.png","tipo":"imagem","largura":"pequena"}]$j$::jsonb where id = '401ffc50-07ff-48f6-a012-4020efd2f3bc'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2022_N3_Q05_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '403c8497-4487-4c5c-bdba-ae51009b849b'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OMERJ2024_NJ_Q02_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '403e81de-b19e-43aa-b192-ecbacaf0c670'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Silvia terminou sua tarefa em 12 minutos (pois 60 ÷ 5 = 12), momento em que Renato fez 36 biscoitos (pois 3 × 12 = 36); portanto, ele deverá fazer mais 24 biscoitos para completar sua tarefa."}]$j$::jsonb where id = '406e79b6-12c4-4a7f-921d-feb9377e3e40'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2025_N3_1F_Q10_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '40a57c00-0066-423e-8102-3b7dea8b46e6'::uuid and blocos is null;
