  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2022_N1_Q13_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '40ef801f-4992-4da8-9df0-1e401efb9693'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2024_N3_Q06_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '4111df9f-b759-4fa6-8f07-b60f9e354166'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781113052357-hdlbb9mm6e7.png","tipo":"imagem","largura":"grande"},{"tipo":"texto","conteudo":"Outra solução (com rudimentos de álgebra): \nSejam T = número total de atletas, \nB = atletas que andam de bicicleta, \nE = atletas que andam de esteira. \n\nDe acordo com o enunciado, B – E = 10; logo, (B - E)/ T = (10 / T), portanto,\n(B / T) - (E / T) = 10 / T\n(8 / 14) - (20 / 42) = 10/T\n(2 / 21) = 10 T; logo, T = 105. \n\nA quantidade dos que andam de bicicleta é B = (8 / 14) × 105 = 60 e a quantidade dos que não andam de bicicleta é 105 - 60 = 45."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781113699074-20env5jr1lt.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '41830bef-81b6-4f15-a261-6247999b4d3e'::uuid and blocos is null;
