  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2015_N3_1F_Q20_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '47847ade-0118-4d0c-ba5b-873895aab301'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2017_N2_1F_Q06_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '48702bfc-ff55-49b2-9ff0-8e9bec5ec604'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Há varias formas de se determinar quantas pizzas foram utilizadas para formar a figura. Por exemplo, contando os pedaços temos 24 + 16 = 40 pedaços e, como cada pizza é dividida em oito pedaços, temos 40 ÷ 8 = 5 pizzas. Outra forma de se determinar isso é observar, na figura, que temos 4 metades de pizzas e mais 4 três quartos de pizzas; como 4 metades é igual a duas pizzas (4 × 1/2 = 4/2 = 2) e 4 três quartos é igual a três pizzas (4 × 3/4 = 12/4 = 3), o total de pizzas utilizado foi de 2 + 3 = 5 pizzas.\n\nUma terceira forma de se determinar quantas pizzas foram utilizadas é olhar para a figura e imaginar três linhas horizontais de pizzas; basta observar que na primeira linha podemos formar 2 pizzas inteiras, na segunda linha, 1 pizza e, na terceira linha, 2 pizzas, totalizando 2 + 1 + 2 = 5 pizzas inteiras."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780846617688-vx6zzqvzpl.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '48a136b3-9d0a-45b0-916b-1557468be12d'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2018_N2_1F_Q08_sol.png","tipo":"imagem"}]$j$::jsonb where id = '48c378a2-5569-4487-b1cf-308424deecf7'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780946267266-w6nsgnu9ea.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '48ee3fc5-a7f0-45a3-8857-6ba9f6a4c9af'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A primeira mamadeira (na ilustração) marca 250 mL, enquanto a segunda marca 75 mL. Para saber quanto Zezé mamou, basta fazer a subtração 250 - 75 = 175. Assim, Zezé mamou 175 mililitros."}]$j$::jsonb where id = '493ad13e-9065-41f3-af35-b6ee252ec384'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2024_N2_Q01_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '496825f4-8a63-45c3-a354-b5235057e637'::uuid and blocos is null;
