  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Paulo comprou 28 comprimidos, em caixas com quantidades de 8 ou de 12 comprimidos cada. A única forma de Paulo fazer essa compra é com uma caixa de 12 comprimidos e duas caixas com 8 comprimidos. Logo, ele gastou 1 x 40 = 40 reais na caixa com 12 comprimidos mais 2 x 25 = 50 reais nas duas caixas com 8 comprimidos, totalizando 40 + 50 = 90 reais gastos nessa compra."}]$j$::jsonb where id = '4d5c7b1f-0fc3-4bfb-b0d7-7fac8f480656'::uuid and blocos is null;
