  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Basta observar a disposição das últimas páginas dos dois livros: "},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780858665592-t610bn7ahs7.png","tipo":"imagem","largura":"pequena"},{"tipo":"texto","conteudo":"Portanto, a distância entre a última página do Volume I até a última página do Volume II é "},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780858709553-qcxtolcmwvo.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '50cab373-0c7a-4800-b323-5af6cf99eba2'::uuid and blocos is null;
