  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"O quadrado maior tem lado medindo 6 cm e o quadrado menor tem lado medindo 2 cm, já que a área de um quadrado é igual ao quadrado da medida de seu lado. Portanto, de acordo com a distribuição geométrica dos quadrados na figura, o terceiro quadrado tem lado medindo 6 − 2 = 4 cm; logo, sua área é 16 cm²."}]$j$::jsonb where id = '57362f1d-d6e8-40a5-a028-aacb8ce42617'::uuid and blocos is null;
