  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"As quantidades de pessoas nas fileiras à frente e atrás de Mônica são múltiplas da quantidade de cadeiras de cada fileira e, como o casal sentou lado a lado, cada fileira deve ter mais do que uma cadeira. O único divisor comum de 14 e 21 que é maior do que 1 é 7 e, assim, podemos concluir que na frente de Mônica havia 2 fileiras e que atrás dela havia 3 fileiras, cada uma com 7 lugares e totalmente preenchidas. Contando ainda com a fileira em que ela estava, obtemos 14 + 21 + 7 = 42 lugares no auditório."}]$j$::jsonb where id = '66635884-b423-429b-8e2d-8f8577cf4c85'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781404248828-x72n1r4fv7j.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781404259976-0s8ma6q8axf.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781404271986-klzka41jz1.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '666cf861-c185-4e04-895f-3fb8cca58ca2'::uuid and blocos is null;
