  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781451880921-seypx5uh85j.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781451890870-6ua2j8gajhf.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '6918342c-9206-45d2-ad41-f61d99054b27'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2024_N3_Q19_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '691a0059-35c6-4bc1-9bd3-66f16f626293'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como os vértices da figura destacada (um octógono) dividem os lados do quadrado em três partes iguais, podemos ligá-los de forma a obter um quadriculado que divide o quadrado em nove quadradinhos iguais. A figura cuja área conhecemos é formada por cinco desses quadradinhos e quatro triângulos, os quais são, cada um deles, metade de\num quadradinho.\nReunindo esses quatro triângulos dois a dois, como na figura, teremos mais dois quadradinhos; portanto, o octógono, cuja área é 28 cm², é equivalente a 5 + 2 = 7 quadradinhos. A área de cada um dos quadradinhos é, portanto, igual a 28 ÷ 7 = 4 cm². Como o quadrado equivale a nove quadradinhos, sua área é 9 x 4 = 36 cm². "},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780797823071-szv57y0htsd.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '692c1964-a255-404c-a3d0-216132f5955f'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2023_N2_Q19_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '696f076c-3304-4eb2-ae09-6a018b6c4e9d'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2022_N3_Q14_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '697e712d-dc05-405b-b399-9cfa433d6ef1'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2015_N1_2F_Q02_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '69b46fe4-8ab6-4cf2-97d5-7fc392cf77f8'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2022_N1_Q10_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '69d1b912-3b72-44f0-9c45-612e57c0a90f'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2022_N2_Q11_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '6a502b68-0ff8-4748-9abf-b5e05156c450'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Observando a planificação, vemos que a menor soma possível para três faces vizinhas de um pequeno dado é 1 + 2 + 4 = 7 e, juntando adequadamente 8 dados na posição em que essas faces com soma mínima formem as faces do cubo grande, concluímos que a menor soma possível dos 24 números que aparecem nas faces do cubo grande é 8 × 7 = 56.\n\nMais detalhadamente, ao juntar os oito dados idênticos formamos um cubo maior e em cada face desse cubo maior aparecem quatro números. Portanto, nas seis faces desse cubo maior aparecem 6 × 4 = 24 números. Por outro lado, cada vértice do cubo maior corresponde a um dos oito vértices do dado e cada vértice do dado tem três de suas faces concorrendo nesse vértice. Assim, os 24 números que aparecem nas seis faces do cubo maior são provenientes de faces comuns dos dados, faces essas que ficaram visíveis após a montagem, incluindo a que fica apoiada sobre a mesa. Logo, a menor soma possível para os números que aparecem nas faces do cubo formado é igual a oito vezes a menor soma possível para as três faces comuns de um vértice de um dado.\n\nAo montar o dado a partir de sua planificação, observamos que as faces opostas serão:\n2 e 5; 1 e 3; 6 e 4\n\nObservamos também que as faces comuns aos vértices do dado serão:"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780931814840-yc108ntqaza.png","tipo":"imagem","largura":"grande"},{"tipo":"texto","conteudo":"Assim, a menor soma possível para os números que aparecem nas faces do cubo formado será 8 × 7 = 56."}]$j$::jsonb where id = '6aa7a24b-c9f0-49d0-8d91-99e3cb17a996'::uuid and blocos is null;
