  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"No total, as bolas pesam 4 quilos. Logo, na figura da esquerda, cada lado pesa 2 quilos, o que nos permite concluir que as bolas 4 e 5 pesam um quilo cada e que, dentre as bolas 1, 2 e 3, uma pesa um quilo e duas pesam meio quilo. Na figura 2, o lado direito é mais pesado. Como as bolas 4 e 5 têm o mesmo peso, concluímos que a bola 2 é mais pesada que a bola 1. Portanto, a bola 2  pesa um quilo e as  bolas 1 e 3 pesam meio quilo cada."}]$j$::jsonb where id = '6e02b927-88d8-43f0-94ec-37c84005ba01'::uuid and blocos is null;
