  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N3_Q06_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '752d5e00-2b3d-42e4-9464-2810822950a9'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"O círculo é composto de quatro regiões. Rotulamos as regiões como na figura. Se começarmos a pintar as regiões a partir da menor (c), teremos quatro cores para fazê-lo. A região em volta, (d), terá apenas três cores disponíveis. As duas outras regiões são vizinhas à região (d) e vizinhas entre si; portanto, a próxima região a ser pintada tem três cores disponíveis e a última, apenas duas, já que é vizinha de duas regiões. Pelo Princípio Multiplicativo, o número total de maneiras possíveis de pintar as regiões do círculo é, portanto, 4 x 3 x 3 x 2 = 72.\n\nObservação: A ordem em que começamos a pintar pode ser outra, mas isso pode exigir mais cuidado. Por exemplo, podemos pintar a figura na seguinte ordem: a, c, b e d. Para (a), temos 4 possibilidades e precisamos dividir em casos. Para a região (c), depende de a cor ser igual ou não à de (a). Se for igual, o número total de possibilidades é 4 x 1 x 3 x 2 = 24, e se a cor de (a) for diferente da de (c), o número de possibilidades é 4 x 3 x 2 x 2 = 48. Assim, seguindo este procedimento, o número total de possibilidades é 48 + 24 = 72."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780844005136-c2sfzju9st6.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '7583bc72-7c0a-4083-9586-1096d2b8e6c5'::uuid and blocos is null;
