  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781473158291-0udkeqybea7.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781473169957-eeavhwf5vl.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '79058119-79e7-4379-a257-eaa60d27eb52'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"a) A 3ª marcação média marca 2,5 cm (25 mm). A 11ª marcação pequena marca 1,3 cm (13 mm). A distância, em milímetros, entre essas marcações é 25 – 13 = 12 mm.\n\nb) Entre cada par de marcações grandes consecutivas há 8 marcações pequenas. A régua inteira possui 30 pares de marcações grandes consecutivas. Logo, há 30 × 8 = 240 marcações pequenas na régua inteira.\n\nc) Para encontrar entre qual par de marcações grandes está a 215ª marcação pequena, devemos calcular o quociente da divisão de 215 por 8. Temos 215 = 26 × 8 + 7. A 215ª marcação pequena está na 7ª marcação pequena depois do 26º par de marcações grandes. A 215ª marcação pequena marca, então, 26,8 cm (268 mm). A marcação que está à distância de 73 milímetros da 215ª marcação pequena ocorre necessariamente antes dessa marcação, senão ela estaria fora da régua. A marcação que está à distância de 73 milímetros da 215ª marcação pequena marca, então, 268 – 73 = 195 milímetros, na 20ª marcação média."}]$j$::jsonb where id = '7936d03f-958f-4a23-aaa4-986e5cdd1078'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Representando graficamente as três situações uma no topo da outra, como na figura abaixo, observamos que a soma das três medidas corresponde a 3 vezes a distância h (o bloco verde debaixo compensa com o bloco verde do topo). Logo, h = (113+80+82)/3 = 91 cm."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780860447895-sqoii3czaji.png","tipo":"imagem","largura":"media"},{"tipo":"texto","conteudo":"OUTRA SOLUÇÃO:\nCada uma das distâncias nas três figuras pode ser expressa em termos de h e das alturas de dois dos blocos:\n\n111 = *h* – bloco verde + bloco azul\n80 =* h* – bloco azul + bloco rosa\n82 = *h* – bloco rosa + bloco verde\n\nCada bloco aparece uma vez nessas igualdades com sinal positivo e outra com sinal negativo. Portanto, ao somá-las, eles se cancelam. Temos, assim: 111 + 80 + 82 = 3*h*\nLogo, 3*h* = 273 e, portanto, *h* = 91 cm."}]$j$::jsonb where id = '797fb10e-b0d3-4b6b-97dd-5d05a1826610'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2024_N3_Q14_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '798b7951-9400-4365-91b8-c678ad0a59f5'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2024_N3_1F_Q13_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '7a51c9f2-f814-477a-9980-e3675014b8b2'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2016_N3_1F_Q09_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '7a7016de-64a0-44e1-8edd-3d9febd14bca'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A soma dos números dos cartões de Ana é 7, logo, ela pegou os cartões de números 1, 2 e 4, pois esta é a única possibilidade de decomposição do número 7 como soma de três parcelas diferentes, cada uma delas compreendida de 1 a 9. Como 23 é ímpar, temos as seguintes alternativas para os números dos cartões de Beto:\n\n- Os três números são ímpares. Isso é impossível, pois a maior soma possível, nesse caso, é 5 + 7 + 9 = 21, menor do que 23.\n- Um número é ímpar e os outros dois são pares: como Ana está com os cartões de números 2 e 4, a única possibilidade é Beto ter pego os cartões de números 6, 8 e 9.\n\nEntão, na mesa ficaram os cartões de números 3, 5 e 7. A diferença entre o maior e o menor deles é 7 – 3 = 4.\n\nOutra solução: A soma máxima de três cartas é 9 + 8 + 7 = 24. Se a soma de Beto é 23, então, ele tem necessariamente as cartas 9, 8 e 6. A soma mínima de três cartas é 1 + 2 + 3 = 6. Se a soma de Ana é 7, então, ela tem necessariamente 1, 2 e 4. Portanto, na mesa temos as cartas 3, 5 e 7, e a diferença entre a maior e a menor é 7 – 3 = 4."}]$j$::jsonb where id = '7a78486a-1c60-46a0-8d67-8545b13f3306'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2022_N1_Q08_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '7a8cdc35-c3a6-4aed-a466-bbaeb30e8c85'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como 50 - 5 = 45, pelo enunciado, podemos deduzir que 45 pirulitos custam R$ 20,25. Logo, um único pirulito custa 20,25 ÷ 45 = 0,45 reais. Logo, 50 pirulitos custam 50 x 0,45 = 22,50 reais"}]$j$::jsonb where id = '7aa8bf90-b982-4908-bf34-1117d631e6fa'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2019_N1_2F_Q02_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '7ab33955-34ee-49bd-98b2-97ca04718e2c'::uuid and blocos is null;
