  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2016_N3_1F_Q05_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '8914c334-dc3e-4b76-af65-1810234c75dd'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Quando a folha é dobrada ao meio, uma das dimensões se mantém e a outra é reduzida à metade, e portanto, o novo perímetro é o original menos o comprimento dessa dimensão. Logo, uma das dimensões da folha é 50 - 35 = 15 cm e a outra dimensão é (50 - 2 x 15)/2 = 10 cm. Ao se dobrar da outra forma, o novo perímetro será 2 x ( 15 + 5) = 40 cm (alternativamente, a redução do perímetro na outra forma é 10 cm; logo, ele passa a ser igual a 40 cm)."}]$j$::jsonb where id = '89e88d69-e62e-438a-a992-43f600f1f91c'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2026_N3_Q12_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '8a0ad040-a2dd-43bb-91bd-05361a154c32'::uuid and blocos is null;
