  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2019_N1_2F_Q01_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '8a35ef83-e7ba-4744-99f0-bcc66c7da852'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2024_N2_1F_Q13_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '8ad4ed8f-c796-4490-b01d-f999835a5b1e'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como a soma dos números dos 4 círculos brancos será igual à soma dos números dos círculos ligados pela linha horizontal, segue que a soma dos números dos círculos brancos ligados pela linha vertical será 2020. De modo semelhante, a soma dos números dos círculos brancos ligados pela linha horizontal será 2020. Assim, a soma total dos números escritos por Priscila nos 4 círculos é 2020 + 2020 = 4040.\n\nOutra solução, utilizando-se rudimentos de álgebra: \na + b + c + d = a + 2020 + c, logo b + d = 2020\na + b + c + d = b + 2020 + d, logo a + c = 2020\nAssim, a + b + c + d = 2020 + 2020 = 4040."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780932524420-erb51o741s.png","tipo":"imagem","largura":"pequena"}]$j$::jsonb where id = '8b6eeb1b-8d86-458e-9835-f6ca54d2f87c'::uuid and blocos is null;
