  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781472908460-4ybjhlez3ok.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '8c1561de-3d92-4271-b993-cdee178e7a5e'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OMERJ2025_N2_Q06_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = '8cb4cb17-dd53-4930-8e36-335bcc8fffc9'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Temos três meninas: Ana, Cláudia e Fabiana, e dois meninos: Joaquim e Pedro, e as condições:\n\nI) havia exatamente duas crianças na casa da árvore;\nII) Pedro, que nasceu em São Paulo, se escondeu junto com Fabiana;\nIII) uma menina se escondeu sozinha;\nIV) Ana não estava sozinha em seu esconderijo;\nV) o menino pernambucano estava na casa da árvore.\n\nDe acordo com a afirmação II), Pedro nasceu em São Paulo e, de acordo com a afirmação V), o menino pernambucano estava na casa da árvore. Portanto, Joaquim estava na casa da árvore.\n\nComo Pedro e Fabiana se esconderam juntos, e como Joaquim estava na casa da árvore, Pedro e Fabiana não podiam estar na casa da árvore, pois, nesse caso, teríamos três crianças na casa da árvore, o que contradiria a afirmação I). A outra criança na casa da árvore deve ser ou Ana ou Cláudia.\n\nComo uma menina se escondeu sozinha (afirmação III) e Ana não estava sozinha (afirmação IV), Ana estava na casa da árvore e Cláudia, sozinha.\n\nConcluímos que Ana e Joaquim estavam escondidos na casa da árvore."}]$j$::jsonb where id = '8d466736-6a71-48c5-a3a1-46385a9a9962'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2022_N3_1F_Q14_sol.png","tipo":"imagem"}]$j$::jsonb where id = '8d969b6e-4d1a-4ff7-b06f-85ed16ac9c53'::uuid and blocos is null;
