  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como Ana pesa 48 quilogramas e a mochila não pode pesar mais do que 12% do peso de Ana, o peso da mochila com o material não pode passar de 0,12 x 48 = 5,76 quilogramas. Como a mochila vazia pesa 760 gramas, ou seja, 0,76 quilogramas, concluímos que o peso máximo do material contido na mochila deve ser igual a  5,76 – 0, 76 = 5 quilogramas. "}]$j$::jsonb where id = '9a6dd5a1-a13a-48e7-bf9c-c0a3f3f9d7be'::uuid and blocos is null;
