  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A figura ilustra a roda-gigante descrita pelo enunciado. Imaginando que os bancos estejam numerados no sentido horário, então os bancos 4, 5, 6 e 7 deverão estar no lado direito da roda-gigante e, como os bancos são igualmente espaçados, deverá haver outros quatro bancos do lado esquerdo. Logo, o total de bancos é 2 + 4 + 4 = 10 bancos."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780789906142-n8xc0gdihor.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = '9f1cf366-887b-4a00-94ed-bfb9ecc8ce4d'::uuid and blocos is null;
