  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781204227764-xt7y69mw0a.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781204245927-ajjbxqwwjf9.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'a2fa38f6-c9ca-480d-90f6-9f54e7bb1e7c'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Rotulamos as áreas como na figura abaixo. A soma das áreas das regiões azuis é\n𝐴 + 𝐶, e a área da região vermelha é 𝐸. Queremos calcular 𝐴 + 𝐶 − 𝐸. Como 𝐴 + 𝐵\né a área do retângulo, 𝐶 + 𝐷 é a área do triângulo e 𝐵 + 𝐷 + 𝐸 é a área do círculo,\ntemos:\n𝐴 + 𝐶 − 𝐸 = (𝐴 + 𝐵) + (𝐶 + 𝐷) − (𝐵 + 𝐷 + 𝐸) = 120 + 29 − 81 = 68 cm².\n"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780799626829-941oc70fg0p.png","tipo":"imagem","largura":"media"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780799685402-771dnya8vko.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'a47123ab-1130-4d4e-acb3-175581ac4632'::uuid and blocos is null;
