  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Vamos analisar cada opção:\nA) **Falsa**, pois no item propaganda o produto A foi o melhor avaliado (recebeu nota 5 contra uma nota 3 do produto B).\nB) **Falsa**, pois o produto de maior utilidade foi o produto B (nota 5), mas o produto menos durável foi o produto C (nota 2).\nC) **Falsa**, pois o produto C obteve a maior pontuação apenas em 2 itens (qualidade e atendimento).\nD) **Falsa**, pois o produto C teve a melhor avaliação em qualidade (nota 5), mas foi o produto A que obteve a melhor avaliação em assistência técnica (nota 4).\nE) **Verdadeira**; de fato, o produto A obteve a maior nota em propaganda (nota 5), mas obteve a nota mais baixa em aparência (nota 1)."}]$j$::jsonb where id = 'b0e8c911-6a93-4a93-aa4b-0429b6a12c56'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2024_N3_Q16_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'b1101665-5eda-42e8-8463-3a0e72569b3f'::uuid and blocos is null;
