  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N3_Q01_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'b1d852d5-5996-403b-a8ef-f01dc15849db'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N2_Q09_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'b265a71e-b7da-4862-923d-5789c6dc0d5e'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Para calcular o perímetro da figura, observamos que o contorno é formado por dois segmentos cujas medidas são 100 cm e 20 cm, um conjunto de segmentos horizontais (que estão acima da base de 100 cm) e um conjunto de segmentos verticais (que estão à esquerda do lado do quadrado maior de 20 cm). A soma dos comprimentos dos segmentos horizontais corresponde à soma dos comprimentos dos lados dos quadrados que foram dispostos lado a lado na parte inferior da figura, e essa soma é 100 cm. Por outro lado, a soma dos comprimentos dos segmentos verticais é igual ao comprimento do lado do quadrado maior, isto é, 20 cm. O perímetro é, portanto, 100 + 20 + 100 + 20 = 240 cm."}]$j$::jsonb where id = 'b2aafffb-80cf-47a0-9c08-6fea9607b213'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2022_N3_1F_Q06_sol.png","tipo":"imagem"}]$j$::jsonb where id = 'b32f56ab-7c89-4f40-acc8-ee226e1bb613'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N3_Q10_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'b39af820-49e1-4b71-8f87-eaffa2876b86'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OMERJ2025_NJ_Q04_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'b3a0e686-5869-48f0-b07a-2a73e1252c95'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"a) Dividimos as 100 pessoas em blocos de 5 pessoas cada e obtemos 100 ÷ 5 = 20 blocos. Como em cada bloco há três mulheres, temos um total de 20 × 3 = 60 mulheres na fila."},{"tipo":"texto","conteudo":"b) Nas cinco primeiras posições, há dois homens, logo, as posições 2, 4 e 5 devem ser ocupadas por mulheres. Por outro lado, nas posições de 2 a 6, já há três mulheres e, portanto, a posição 6 deve ser ocupada por um homem. Daqui para frente o padrão se repete: nas posições de 3 a 7 já existem dois homens, então, a posição 7 deve ser ocupada por uma mulher, e assim por diante. Observamos que, de cinco em cinco, a sequência de homens e mulheres é sempre a mesma: HMHMM, HMHMM, HMHMM..."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781031547601-584twbnsop.png","tipo":"imagem","largura":"grande"},{"tipo":"texto","conteudo":"c) A resposta correta é essa porque as últimas posições, de 95 a 100, também apresentam a \nsequência HMHMM."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781031776421-g1gbjzgi2zu.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = 'b3a529f9-3cca-4fd2-9be7-877b91aca5f6'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A sopa não pode ter salsinha e um de seus ingredientes deve ser alho; desse maneira, Michel deve fazer a sopa com mais dois ou três ingredientes entre cebola, batata e cenoura. Ele pode escolher exatamente dois ingredientes de 3 maneiras diferentes: cebola + batata, cebola + cenoura e batata + cenoura. Além disso, ele pode escolher três ingredientes de uma única maneira: cebola + batata + cenoura. Dessa maneira, Michel pode fazer uma sopa que atenda a seus dois filhos de 3 + 1 = 4 maneiras diferentes."}]$j$::jsonb where id = 'b3b349ea-8cd2-4aa5-a093-ede527c84ed8'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2016_N3_1F_Q07_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'b437cbe7-64ea-4c32-b835-4ac9222db72b'::uuid and blocos is null;
