  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2016_N1_2F_Q05_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'b4c8d2df-9e15-4ce9-b8f2-0cc5f082ebdf'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Como Aurélio está acostumado a digitar sua senha sem olhar para o teclado, ele basicamente digita pelas posições. Começa pela tecla central, vai para quina superior da esquerda, desce uma posição e, em seguida, termina na quina inferior da direita. Rodando o teclado 180º e repetindo o movimento, ele só pode ter digitado da seguinte maneira:"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780847963202-xxms5hlli5.png","tipo":"imagem","largura":"pequena"},{"tipo":"texto","conteudo":"Portanto, dentre as alternativas apresentadas, a única que pode representar o número digitado por Aurélio é a que aparece na letra B, 5961."}]$j$::jsonb where id = 'b50d6871-4951-42bb-958f-c01a27ababc2'::uuid and blocos is null;
