  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Observe que a figura é formada por quadradinhos inteiros, em verde; por metades de 1 quadradinho, assinalados em azul; e por metades de retângulos formados por dois quadradinhos, assinalados em vermelho. Cada uma dessas áreas vale 1, 1/2 e 1 da área de um quadradinho, respectivamente. Logo, a área total da figura equivale a 12 + 4 x (1/2) + 8 x 1 = 22 quadradinhos."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780784123608-oqv2u6scot.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = 'b9493872-16f8-4b34-a2af-601633d65020'::uuid and blocos is null;
