  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Depois de retirada uma fileira inteira, foi retirada de cada fileira restante uma cadeira na quinta posição. Como foram retiradas 9 cadeiras nessa posição, concluímos que depois da retirada de uma fileira inteira sobraram 9 fileiras e cada fileira, depois de retirada a cadeira na quinta posição, ficou com 6 – 1 = 5 cadeiras. Logo, sobraram 9 × 5 = 45 cadeiras.\n\nNa figura, a representação de um possível arranjo das cadeiras. Na horizontal, uma possível linha suprimida e, em seguida, a coluna formada pelas quintas cadeiras das fileiras, também suprimida."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780944082580-tjq3xseigps.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = 'bd76e6ec-b83c-4b24-b8ef-270ef459213d'::uuid and blocos is null;
