  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Devemos em primeiro lugar resolver as expressões entre parêntesis, seguindo a ordem de prioridade das operações. Essa ordem é a seguinte: fazer primeiramente as multiplicações e divisões para, a seguir, realizar as adições e subtrações. Assim,\na alternativa A) está correta pois, 4 + (4 − 4) × 4 = 4 + 0 × 4 = 4 + 0 = 4.\na alternativa B) está correta pois, (4 × 4 + 4) ÷ 4 = (16 + 4) ÷ 4 = 20 ÷ 4 = 5.\na alternativa C) está errada pois, 4 + 4 ÷ 4 + 4 = 4 + 1 + 4 = 9 ≠ 6.\na alternativa D) está correta pois, 44 ÷ 4 − 4 = 11 − 4 = 7.\na alternativa E) está correta pois, 4 + 4 + 4 − 4 = 8 + 4 − 4 = 12 − 4 = 8.\n\nUma interessante brincadeira é tentar escrever todos os números de 1 a 100 usando quatro números 4. Por exemplo, o número 6 pode ser escrito como (4 + 4) ÷ 4 + 4; se ficar muito difícil, podemos permitir o uso de raízes quadradas, como em 20 = √4 × √4 × 4 + 4, ou outros símbolos matemáticos, mas sempre utilizando quatro números 4."}]$j$::jsonb where id = 'c3541067-146e-4de7-b78f-b02e4b9f5480'::uuid and blocos is null;
