  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Em virtude da simetria da figura, as medidas das áreas dos dois triângulos coloridos de azul que estão na esquerda são iguais às medidas das áreas dos triângulos coloridos de vermelho na direita. Portanto, a área procurada é igual à área do triângulo CDE. Como E é o ponto médio do lado AD, a área do triângulo CDE é metade da área do triângulo ACD e este, por sua vez, é metade da área do retângulo ABCD. Assim, a soma das áreas coloridas de azul é (1/2) × (1/2) × 1 = 1/4 cm²."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780886700392-jp595c1jyum.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = 'c43b0dad-c38a-4625-9ba2-56d47a4e6f2d'::uuid and blocos is null;
