  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Se numerarmos com I, II, III e IV as faces da figura na ordem em que elas serão coladas na montagem, como na figura, podemos verificar se, em cada imagem, as faces visíveis estão representadas adequadamente.\nNa Imagem 1, temos coladas corretamente as faces I e IV; na Imagem 2, aparecem coladas as faces II e IV, o que é incorreto, pois elas são opostas; a Imagem 3 nos apresenta corretamente coladas as faces I e II, o que está correto; na Imagem 4, temos coladas as faces I e IV, mas a posição das faces está incorreta (é importante aqui observar a inclinação dos segmentos de reta da face IV); finalmente, na Imagem 5, temos corretamente coladas as faces III e IV. Portanto, somente as imagens 1, 3 e 5 podem representar a torre em miniatura montada por Pedro."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780790348495-uyif5wm6ck.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = 'ccf07b78-e96e-4dbc-bf5b-74cb4c0db88c'::uuid and blocos is null;
