  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Basta observar que da Torre 1 para a Torre 2 foram acrescentados 5 = 2 + 1 x 3 cartões. De fato, para construir a Torre 2 a partir da Torre 1, foram acrescentados dois novos cartões (em contato com a mesa) e, a seguir, no topo foram acrescentados mais 3 cartões. De modo análogo, para construir a Torre 3 a partir da Torre 2, foram acrescentados à Torre 2 mais 8 = 2 + 2 x 3 cartões, ou seja, dois novos cartões em contato com a mesa e 2 grupos de três cartões acima deles. Continuando, da Torre 3 para a 4 devem ser acrescentados 2 + 3 x 3 = 11 cartões e assim sucessivamente, sempre colocando 2 cartões novos em contato com a mesa e mais grupos de 3 cartões até completar a torre seguinte. Concluímos, desse modo, que da torre 10 para a torre 11 devem ser acrescentados 2 + 10 x 3 = 32 cartões. Observe que a Torre N+1 é obtida da Torre N acrescentando-se 3N + 2 cartões."}]$j$::jsonb where id = 'ce9d5ccf-64ec-4623-af6f-d00950464cac'::uuid and blocos is null;
