  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Luísa comprou três pedaços do bolo que estava dividido em 8 partes iguais, e João comprou os 5 pedaços restantes. Como 3/8 do bolo custou R$ 4,50, cada fatia (ou seja, 1/8 do bolo) custou R$ 1,50. Portanto, João pagou 5 x R$ 1,50 = R$ 7,50."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780799167756-abqfkt7ezeh.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = 'd6f322d7-233d-40cb-aca2-f020053c6b03'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2022_N3_1F_Q15_sol.png","tipo":"imagem"}]$j$::jsonb where id = 'd6f874c5-2001-4eb3-9df8-1f020794a82d'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/OBMEP2024_N2_1F_Q03_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'd726d94d-42ec-43b2-b636-e1a21e541397'::uuid and blocos is null;
  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Dado que a temperatura máxima da terça-feira foi de 25ºC, temos que a temperatura máxima de segunda-feira, 4ºC mais baixa do que a de terça-feira, foi de 21ºC. \n\nConsequentemente, a temperatura máxima de quarta-feira, 6ºC mais baixa do que a de segunda-feira, foi de 21ºC - 6ºC = 15ºC."}]$j$::jsonb where id = 'd728668f-57e9-414f-ae65-d8e3027c29bc'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2023_N1_Q13_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'd7443f88-83ae-485e-b9a8-6373f785f5e8'::uuid and blocos is null;
