  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A parte vermelha é formada por um quadradinho mais 4 metades de quadradinhos. Essas 4 metades juntas têm a mesma área que a de 2 quadradinhos. Assim, a área total da parte vermelha é igual à área de 1 + 2 = 3 quadradinhos. Como essa área é de 6 cm², cada quadradinho tem uma área de 2 cm². O quadrado inteiro é formado por 9 quadradinhos. Assim, a área em azul equivale à área de 9 – 3 = 6 quadradinhos, que é igual a 6 x 2 = 12 cm²."}]$j$::jsonb where id = 'da676506-89c3-4929-b9d7-c5e2b4499e71'::uuid and blocos is null;
  update solucao set blocos = $j$[{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/JACOB2025_N3_Q20_sol.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'da839b68-dec7-4c18-ae73-66cf143b10df'::uuid and blocos is null;
