  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"a)"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781112042819-erdcvq79pwi.png","tipo":"imagem","largura":"media"},{"tipo":"texto","conteudo":"b)"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781112092724-isb6t57ikra.png","tipo":"imagem","largura":"media"},{"tipo":"texto","conteudo":"c) Os 3 círculos vazios da segunda linha deverão ser preenchidos, em alguma ordem, pelos números 1, 2 e 3. Portanto, os números dos círculos vazios da primeira linha serão escolhidos entre {4, 5, 7, 8}; mas, nesse conjunto, não há 3 elementos tais que a subtração de dois deles resulte no terceiro, diferente das parcelas. Logo, o preenchimento é impossível."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781112203023-poj8w1ymaf9.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'e42cb4fb-1fb5-47b8-b081-e9272cd4d427'::uuid and blocos is null;
