  update solucao set blocos = $j$[{"tipo":"texto","conteudo":""},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781205587551-r9y3wkckzjm.png","tipo":"imagem","largura":"grande"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1781205599777-ycl6y7v8zq.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'e45e36c8-24c4-4cae-9f51-5551c041880e'::uuid and blocos is null;
