  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Para ir até o doce andando sobre as linhas da figura, a formiguinha deve andar 4 vezes para frente e 5 vezes para baixo. Um caminho de menor comprimento possível ocorre quando ela anda simultaneamente para frente e para baixo, na diagonal, o máximo de vezes possível. De acordo com as linhas da figura, esse caminho de menor tamanho possível ocorre quando ela anda 4 vezes na diagonal, escolhendo uma vez só para andar para baixo. Logo, se a letra D representar andar na diagonal e a letra B andar para baixo, os caminhos de menor comprimento possível são:\n\n- D+D+D+D+B;\n- D+D+D+B+D;\n- D+D+B+D+D;\n- D+B+D+D+D;\n- B+D+D+D+D.\n\nPortanto, são 5 os caminhos de menor comprimento possível.\n"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780854564049-0kog4z1iij8d.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'e5ab83fe-cd59-4d88-bbe0-f1229d16074d'::uuid and blocos is null;
