  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Para obter o maior resultado possível, devemos fazer com que os termos que contribuem positivamente na conta sejam os maiores possíveis e o termo que contribui negativamente seja o menor possível. Como estamos usando o sistema de numeração posicional decimal, na primeira parcela da conta devemos colocar o maior dos algarismos disponíveis na casa das centenas (o algarismo 8):"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780785339458-h000i4szwtq.png","tipo":"imagem","largura":"grande"}]$j$::jsonb where id = 'eb487738-67b0-4250-bd35-c777814c4bd8'::uuid and blocos is null;
