  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Podemos decompor a figura sombreada em um quadrado e um triângulo, traçando um segmento de O até o ponto médio N do lado do quadrado, conforme indicado na figura. Assim, a área da região sombreada é igual a (1/4) + (1/8) da área do quadrado com centro em O, ou seja, a área sombreada é igual a 5 + 2,5 = 7,5 cm²."},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780786472713-gi2dn72cbr.png","tipo":"imagem","largura":"media"}]$j$::jsonb where id = 'fa2aa38a-bbb3-41c4-b7d9-3b5815b10b9f'::uuid and blocos is null;
