  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"Observemos a figura abaixo.\n"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780930063841-en4g84pfpoi.png","tipo":"imagem","largura":"pequena"},{"tipo":"texto","conteudo":"Como os lados da folha menor são paralelos aos lados da folha maior, a soma dos comprimentos dos segmentos azuis é igual à diferença entre os comprimentos dos lados horizontais da folha branca e da folha cinza, ou seja, é igual a 70 − 40 = 30 cm; analogamente, a soma dos comprimentos dos segmentos vermelhos é igual a 80 − 50 = 30 cm. Desse modo, ao dobrarmos a folha branca pelas linhas pontilhadas, obteremos a figura abaixo, em que o retângulo cinza tem dimensões horizontal 40 − 30 = 10 cm e vertical 50 − 30 = 20 cm; sua área é, então, 200 cm².\n\n"},{"url":"https://ebdazvyyunilbkygtevn.supabase.co/storage/v1/object/public/questoes/solucoes/1780930273469-9v4m8fi3z7h.png","tipo":"imagem","largura":"media"},{"tipo":"texto","conteudo":"Observe que a posição da folha cinza sobre a branca não é importante, desde que as margens vertical e horizontal das folhas mantenham-se respectivamente paralelas, ou seja, as distâncias 12 cm e 14 cm não são relevantes; de fato, mudando-as, a área da região cinza não coberta, após a dobra, continua a mesma."}]$j$::jsonb where id = 'fb60825b-87f5-4410-a32b-c1630debefb2'::uuid and blocos is null;
