  update solucao set blocos = $j$[{"tipo":"texto","conteudo":"A figura 1 é formada por 5 bolinhas em formato de Y e, a partir dela, quando passamos de uma figura para a seguinte, a próxima figura tem 3 bolinhas acrescidas, sendo uma em cada ponta do Y. Logo, a 15a figura terá 5 + 3 x 14 = 47 bolinhas. Mais geralmente, a quantidade de bolinhas na n-ésima figura é 5 + 3(n-1) = 3n + 2."}]$j$::jsonb where id = 'fc3f99f6-b00b-4cdd-bdb7-e7dd9a11b84e'::uuid and blocos is null;
